{
  "name": "Process Form Submissions",
  "description": "Summarise form webhook submissions, route urgent ones to Discord, and log all submissions to a Google Sheet.",
  "nodes": [
    {
      "id": "webhook",
      "type": "core.webhook_trigger",
      "label": "Form Webhook",
      "config": {
        "requiredFields": []
      }
    },
    {
      "id": "summarise",
      "type": "ai.llm",
      "label": "Summarise Submission",
      "config": {
        "prompt": "Summarise this form submission in one concise sentence: {{trigger.message}}"
      }
    },
    {
      "id": "decide",
      "type": "ai.agent",
      "label": "Classify Urgency",
      "config": {
        "objective": "Determine if this form submission is urgent or normal.",
        "choices": [
          "urgent",
          "normal"
        ]
      }
    },
    {
      "id": "branch_urgent",
      "type": "core.branch",
      "label": "Is Urgent?",
      "config": {
        "left": "{{input.decision}}",
        "operator": "equals",
        "right": "urgent"
      }
    },
    {
      "id": "discord",
      "type": "integration.discord",
      "label": "Post Urgent to Discord",
      "config": {
        "content": "Urgent submission: {{steps.summarise.output.text}}"
      }
    },
    {
      "id": "sheets",
      "type": "integration.sheets",
      "label": "Log to Google Sheet",
      "config": {
        "spreadsheetId": "",
        "sheet": "Sheet1",
        "values": [
          "{{trigger.message}}",
          "{{steps.summarise.output.text}}"
        ],
        "valueInputOption": "RAW"
      }
    }
  ],
  "edges": [
    {
      "source": "webhook",
      "target": "summarise",
      "sourceHandle": null
    },
    {
      "source": "summarise",
      "target": "decide",
      "sourceHandle": null
    },
    {
      "source": "decide",
      "target": "branch_urgent",
      "sourceHandle": null
    },
    {
      "source": "branch_urgent",
      "target": "discord",
      "sourceHandle": "true"
    },
    {
      "source": "branch_urgent",
      "target": "sheets",
      "sourceHandle": "false"
    },
    {
      "source": "discord",
      "target": "sheets",
      "sourceHandle": null
    }
  ],
  "unsupported": []
}

