{
  "name": "Filter and sort products by price",
  "description": "Filters a pasted list of products to keep those under 50, sorts them from cheapest to most expensive, and logs the result.",
  "nodes": [
    {
      "id": "trigger",
      "type": "core.manual_trigger",
      "label": "Input products",
      "config": {}
    },
    {
      "id": "filter_products",
      "type": "transform.filter",
      "label": "Keep under 50",
      "config": {
        "items": "{{trigger.products}}",
        "field": "price",
        "operator": "less_than",
        "value": 50
      }
    },
    {
      "id": "sort_products",
      "type": "transform.sort",
      "label": "Sort by price",
      "config": {
        "items": "{{steps.filter_products.output.items}}",
        "field": "price",
